"""The environment and the agents a run's settings name (CORE-01, DATA-02)."""

from collections.abc import Callable
from functools import partial
from typing import Literal

from rllab.agents import DQNAgent, TabularAgent
from rllab.core import Agent, Env, RunSettings, TeamSpec
from rllab.envs import Corridor, Snake


def make_env(settings: RunSettings) -> Callable[[], Env]:
    """A zero-argument factory of the environment `settings.env` names."""
    if settings.env == "snake":
        view: Literal["compact", "grid"] = "grid" if settings.view == "grid" else "compact"
        return partial(Snake, view=view, rewards=settings.rewards)
    if settings.env == "corridor":
        return partial(Corridor, rewards=settings.rewards)
    raise ValueError(f"env {settings.env!r} is not built in this milestone: M1 has snake, corridor")


def make_agent(settings: RunSettings, env: Env) -> dict[str, Agent]:
    """One agent per team of `env.teams`, sized from its TeamSpec, with the ablation switch."""
    return {name: _learner(settings, team) for name, team in env.teams.items()}


def _learner(settings: RunSettings, team: TeamSpec) -> Agent:
    """The learner `settings.agent` names for one team, with `settings.ablation` applied."""
    if settings.agent == "tabular":
        return TabularAgent(
            team.actions.n,
            settings.params,
            settings.exploration,
            seed=settings.seed,
            explore_enabled=settings.ablation != "no_explore",
        )
    if settings.agent == "dqn":
        ablation: Literal["none", "no_memory", "no_target"] = (
            "none" if settings.ablation == "no_explore" else settings.ablation
        )
        return DQNAgent(
            team, settings.params, settings.exploration, seed=settings.seed, ablation=ablation
        )
    raise ValueError(f"agent {settings.agent!r} is not a learner make_agent builds: tabular, dqn")

